PAYLOAD = json.loads("{\"tools/common.py\": {\"sha_head\": null, \"content\": \"#!/usr/bin/env python3\\n\\\"\\\"\\\"common.py \\u2014 Fonctions partagees des outils gtamaplib.\\n\\nNE PAS dupliquer ces fonctions dans les outils: la journee du 2026-06-10 a\\nproduit 3 copies de cam_rms, 2 de ray_ls_point et 2 conventions JSON\\ndivergentes (un dump sort_keys/indent=1 a reecrit pixels.json au complet,\\n8227 insertions de churn pur). Tout nouvel outil importe d'ici.\\n\\n    sys.path.insert(0, <racine>)\\n    from tools.common import cam_rms, get_cam, ray_ls_point, save_json\\n    (ou: sys.path.insert(0, <racine>/tools); from common import ...)\\n\\\"\\\"\\\"\\nimport json\\nimport math\\nimport os\\nimport sys\\n\\n_ROOT = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))\\nif _ROOT not in sys.path:\\n    sys.path.insert(0, _ROOT)\\nimport gtamaplib as ml\\nimport gtamapdata as md\\n\\ntry:\\n    import numpy as np\\nexcept ImportError:  # ray_ls_point devient indisponible, le reste marche\\n    np = None\\n\\n\\ndef get_cam(cam_name, cam_state=None):\\n    \\\"\\\"\\\"Camera prete a projeter. Gotcha #5: chaque ml.get_camera() peut\\n    retourner une instance differente \\u2014 on set TOUJOURS xyz/ypr/fov avant\\n    get_pixel. cam_state optionnel: dict {'xyz','ypr','fov'} (etat simule)\\n    au lieu de l'etat disque md.cameras.\\\"\\\"\\\"\\n    cam = ml.get_camera(cam_name)\\n    st = cam_state if cam_state is not None else md.cameras[cam_name]\\n    cam.set_xyz(tuple(st[\\\"xyz\\\"]))\\n    cam.set_ypr(tuple(st[\\\"ypr\\\"]))\\n    cam.set_fov(tuple(st[\\\"fov\\\"]))\\n    return cam\\n\\n\\ndef cam_rms(cam_name, lm_override=None, cam_state=None, lms=None):\\n    \\\"\\\"\\\"RMS arcmin d'une cam \\u2014 LA formule canonique (identique a\\n    compute_confidence_tiers): dx*hfov/w*60, dy*vfov/h*60, sqrt(mean(d2)).\\n\\n    lm_override: dict {lm_name: xyz} prioritaire sur l'etat courant.\\n    lms: dict complet {lm_name: xyz|None} remplacant md.landmarks (etat\\n         simule, ex: guarded_apply). lm_override s'applique par-dessus.\\n    Retourne None si aucune observation valide.\\\"\\\"\\\"\\n    obs = md.pixels.get(cam_name)\\n    if not obs or cam_name not in md.cameras:\\n        return None\\n    cam = get_cam(cam_name, cam_state)\\n    base = lms if lms is not None else md.landmarks\\n    acc = n = 0\\n    for ln, px in obs.items():\\n        if px is None:\\n            continue\\n        x = (lm_override or {}).get(ln, base.get(ln))\\n        if x is None:\\n            continue\\n        try:\\n            p = cam.get_pixel(x)\\n        except Exception:\\n            continue\\n        if p is None:\\n            continue\\n        dx = (p[0] - px[0]) * cam.hfov / cam.w * 60\\n        dy = (p[1] - px[1]) * cam.vfov / cam.h * 60\\n        acc += dx * dx + dy * dy\\n        n += 1\\n    return math.sqrt(acc / n) if n else None\\n\\n\\ndef ray_ls_point(rays):\\n    \\\"\\\"\\\"Point least-squares minimisant la distance a tous les rayons\\n    (origin, direction). Releve numpy.linalg.LinAlgError si degenere.\\\"\\\"\\\"\\n    A = np.zeros((3, 3)); b = np.zeros(3)\\n    for o, d in rays:\\n        d = np.asarray(d, float); d /= np.linalg.norm(d)\\n        P = np.eye(3) - np.outer(d, d)\\n        A += P; b += P @ np.asarray(o, float)\\n    return np.linalg.solve(A, b)\\n\\n\\ndef pixel_observers(require_existing_cam=True):\\n    \\\"\\\"\\\"Index {lm_name: [cam_names]} des markings non-nuls.\\\"\\\"\\\"\\n    out = {}\\n    for c, obs in md.pixels.items():\\n        if require_existing_cam and c not in md.cameras:\\n            continue\\n        for l, px in obs.items():\\n            if px is not None:\\n                out.setdefault(l, []).append(c)\\n    return out\\n\\n\\ndef save_json(path, data):\\n    \\\"\\\"\\\"Ecriture canonique du projet: indent=2, SANS sort_keys (ordre\\n    d'insertion preserve, comme gtamapdata.update_*), atomique\\n    (tmp + os.replace \\u2014 un crash mid-write ne corrompt jamais le fichier).\\\"\\\"\\\"\\n    tmp = path + \\\".tmp\\\"\\n    with open(tmp, \\\"w\\\") as f:\\n        json.dump(data, f, indent=2)\\n    os.replace(tmp, path)\\n\"}, \"tools/audit/rms_snapshot.py\": {\"sha_head\": \"9cb4ea734d4a\", \"content\": \"#!/usr/bin/env python3\\n\\\"\\\"\\\"rms_snapshot.py \\u2014 READ-ONLY. Per-cam RMS (arcmin) computed FRESH from disk.\\n\\nSame arcmin formula as compute_confidence_tiers.py (dx*hfov/w*60, dy*vfov/h*60).\\nWrites tools/generated/rms_snapshot_<tag>.json for before/after diffing.\\n\\nUsage: python3 tools/audit/rms_snapshot.py --tag baseline\\n\\\"\\\"\\\"\\nimport argparse, json, math, os, sys\\n\\nROOT = os.path.dirname(os.path.dirname(os.path.dirname(os.path.abspath(__file__))))\\nsys.path.insert(0, ROOT)\\n\\nimport gtamapdata as md\\nsys.path.insert(0, os.path.join(ROOT, \\\"tools\\\"))\\nfrom common import cam_rms\\n\\n\\ndef main():\\n    ap = argparse.ArgumentParser()\\n    ap.add_argument(\\\"--tag\\\", required=True)\\n    args = ap.parse_args()\\n\\n    cameras = md.cameras\\n    landmarks = md.landmarks          # name -> xyz\\n    landmarks_meta = md.landmarks_meta\\n    pixels = md.pixels\\n\\n    out = {}\\n    for cam_name, lm_pixels in pixels.items():\\n        if cam_name not in cameras:\\n            continue\\n        rms = cam_rms(cam_name)\\n        if rms is not None:\\n            n_obs = sum(1 for l, p in lm_pixels.items()\\n                        if p is not None and landmarks.get(l) is not None)\\n            out[cam_name] = {\\\"rms_arcmin\\\": round(rms, 3), \\\"n_obs\\\": n_obs}\\n\\n    # global + zone rollup (zone inferred from landmarks seen, majority vote)\\n    lm_zone = {n: (landmarks_meta.get(n) or {}).get(\\\"zone\\\") for n in landmarks}\\n    zone_acc = {}\\n    for cam_name, lm_pixels in pixels.items():\\n        if cam_name not in out:\\n            continue\\n        zones = [lm_zone.get(l) for l in lm_pixels if lm_zone.get(l)]\\n        zone = max(set(zones), key=zones.count) if zones else \\\"unknown\\\"\\n        out[cam_name][\\\"zone\\\"] = zone\\n        zone_acc.setdefault(zone, []).append(out[cam_name][\\\"rms_arcmin\\\"])\\n\\n    summary = {\\n        \\\"n_cams\\\": len(out),\\n        \\\"global_median_arcmin\\\": round(sorted(v[\\\"rms_arcmin\\\"] for v in out.values())[len(out) // 2], 3),\\n        \\\"global_mean_arcmin\\\": round(sum(v[\\\"rms_arcmin\\\"] for v in out.values()) / len(out), 3),\\n        \\\"zones\\\": {z: {\\\"n\\\": len(v), \\\"median\\\": round(sorted(v)[len(v) // 2], 3)} for z, v in sorted(zone_acc.items())},\\n    }\\n\\n    dest = os.path.join(ROOT, \\\"tools\\\", \\\"generated\\\", f\\\"rms_snapshot_{args.tag}.json\\\")\\n    with open(dest, \\\"w\\\") as f:\\n        json.dump({\\\"summary\\\": summary, \\\"cams\\\": out}, f, indent=1, sort_keys=True)\\n\\n    print(f\\\"# rms_snapshot tag={args.tag} | cams={summary['n_cams']} \\\"\\n          f\\\"median={summary['global_median_arcmin']}' mean={summary['global_mean_arcmin']}'\\\")\\n    for z, s in summary[\\\"zones\\\"].items():\\n        print(f\\\"  {z:<16} n={s['n']:<4} median={s['median']}'\\\")\\n    print(f\\\"-> {dest}\\\")\\n\\n\\nif __name__ == \\\"__main__\\\":\\n    main()\\n\"}, \"tools/audit/keys_z_bias_analysis.py\": {\"sha_head\": \"d486dd0f8834\", \"content\": \"#!/usr/bin/env python3\\n\\\"\\\"\\\"keys_z_bias_analysis.py \\u2014 READ-ONLY. Where do the rays say sea level is?\\n\\nFor every LM with z_constraint {\\\"type\\\":\\\"fixed\\\",\\\"value\\\":0.0}, re-triangulate\\nthe point FREELY (least-squares closest point to all observer rays, current\\ncam poses) and report the free z per zone. A coherent per-zone offset means\\nreferential bias; scatter means the markings aren't at the waterline.\\n\\\"\\\"\\\"\\nimport json, math, os, sys\\n\\nimport numpy as np\\n\\nROOT = os.path.dirname(os.path.dirname(os.path.dirname(os.path.abspath(__file__))))\\nsys.path.insert(0, ROOT)\\nimport gtamapdata as md\\nsys.path.insert(0, os.path.join(ROOT, \\\"tools\\\"))\\nfrom common import get_cam, pixel_observers, ray_ls_point\\n\\n\\n\\n\\ndef main():\\n    observers = pixel_observers(require_existing_cam=False)\\n\\n    rows = []\\n    for lm_name, meta in md.landmarks_meta.items():\\n        zc = (meta or {}).get(\\\"z_constraint\\\")\\n        if not zc or zc.get(\\\"type\\\") != \\\"fixed\\\" or abs(zc.get(\\\"value\\\", 1)) > 1e-9:\\n            continue\\n        obs_cams = observers.get(lm_name, [])\\n        rays = []\\n        for cn in obs_cams:\\n            if cn not in md.cameras:\\n                continue\\n            cam = get_cam(cn)\\n            try:\\n                d = cam.get_pixel_direction(md.pixels[cn][lm_name])\\n            except Exception:\\n                continue\\n            if d is None:\\n                continue\\n            rays.append((md.cameras[cn][\\\"xyz\\\"], d))\\n        if len(rays) < 2:\\n            continue\\n        try:\\n            p = ray_ls_point(rays)\\n        except np.linalg.LinAlgError:\\n            continue\\n        zone = (meta or {}).get(\\\"zone\\\") or \\\"?\\\"\\n        disk_z = md.landmarks[lm_name][2] if md.landmarks.get(lm_name) is not None else None\\n        rows.append((zone, lm_name, len(rays), float(p[2]), disk_z))\\n\\n    byzone = {}\\n    for zone, name, n, free_z, disk_z in rows:\\n        byzone.setdefault(zone, []).append((name, n, free_z, disk_z))\\n\\n    print(f\\\"# {len(rows)} LM contraints z=0 avec >=2 rayons, re-triangules librement\\\\n\\\")\\n    for zone in sorted(byzone):\\n        zs = sorted(v[2] for v in byzone[zone])\\n        med = zs[len(zs)//2]\\n        q1, q3 = zs[len(zs)//4], zs[3*len(zs)//4]\\n        print(f\\\"## {zone}: n={len(zs)}  median_free_z={med:+.2f}m  IQR=[{q1:+.2f}, {q3:+.2f}]\\\")\\n        for name, n, fz, dz in sorted(byzone[zone], key=lambda v: v[2]):\\n            tag = \\\" <-- VIOLATION DISK\\\" if dz is not None and abs(dz) > 0.5 else \\\"\\\"\\n            print(f\\\"    {fz:+7.2f}m  (rays={n}, disk_z={dz:+.2f})  {name}{tag}\\\")\\n        print()\\n\\n\\nif __name__ == \\\"__main__\\\":\\n    main()\\n\"}, \"tools/refine/free_waterline_z.py\": {\"sha_head\": \"4eb7397fb098\", \"content\": \"#!/usr/bin/env python3\\n\\\"\\\"\\\"free_waterline_z.py \\u2014 Retire le z_constraint fixed 0.0 des LM \\\"ligne d'eau\\\"\\nnaturelle et les re-triangule librement (LS multi-rayons, poses actuelles).\\n\\nDOCTRINE (analyse 2026-06-10, tools/audit/keys_z_bias_analysis.py):\\nLa ligne d'eau VISIBLE dans les frames GTA VI n'est PAS le datum z=0 du moteur.\\nRe-triangulation libre des LM contraints: mediane Keys -1.30m, spread -2.9 a\\n+0.35 (pente de plage, maree, imprecision a faible parallaxe). Confirme par la\\nleak Ocean near Keys (E) (pose HUD ground truth) qui place sa ligne d'eau a\\n-0.60m. Ni biais rigide de zone, ni maree par frame: c'est le datum qui etait\\nfaux. z_constraint fixed 0.0 reste valide UNIQUEMENT pour les structures\\nconstruites plates verifiees (quais, seawalls, piscines) \\u2014 pas les rivages.\\n\\nMesure (sandbox): liberer les 5 LM snappes ameliore toutes les observatrices,\\ndont la LEAK Ocean near Keys (E): 4.70' -> 0.03'. Aucune cam ne regresse.\\n\\nCibles: 10 LM leonida_keys (5 en violation disque + 5 snappes) + Di Lido\\nIsland (N) (vice_city; marking a +3..+5m = vegetation, pas l'eau).\\n\\nEcrit via md.update_landmark(..., z_constraint=None) \\u2014 JAMAIS de bypass JSON.\\nDry-run par defaut; --apply pour ecrire (backup landmarks.json.bak_waterline).\\n\\\"\\\"\\\"\\nimport argparse, json, math, os, shutil, sys\\n\\nimport numpy as np\\n\\nROOT = os.path.dirname(os.path.dirname(os.path.dirname(os.path.abspath(__file__))))\\nsys.path.insert(0, ROOT)\\nimport gtamapdata as md\\nsys.path.insert(0, os.path.join(ROOT, \\\"tools\\\"))\\nfrom common import cam_rms as _common_cam_rms, get_cam, pixel_observers, ray_ls_point\\n\\n# policy \\\"keep\\\": clear le constraint, garde le xyz disque (deja une\\n# triangulation libre \\u2014 la bouger en LS coutait Key Lento +0.47' et\\n# Venetian +0.35', au-dessus de la barre 0.25). policy \\\"ls\\\": re-triangule\\n# (snappes a 0, la liberation est mesuree gagnante, max regression 0.00).\\nTARGETS = {\\n    \\\"Island J (E)\\\": \\\"keep\\\", \\\"Island J (W)\\\": \\\"keep\\\", \\\"Island G (E)\\\": \\\"keep\\\",\\n    \\\"Island G (W)\\\": \\\"keep\\\", \\\"Island V (S)\\\": \\\"keep\\\",\\n    \\\"Key Lento (J)\\\": \\\"ls\\\", \\\"Key Lento (A)\\\": \\\"ls\\\", \\\"Sombrero Key Light (B)\\\": \\\"ls\\\",\\n    \\\"Island A (W)\\\": \\\"ls\\\", \\\"Blimp Bay\\\": \\\"ls\\\",\\n    \\\"Di Lido Island (N)\\\": \\\"keep\\\",\\n}\\n\\n\\ndef cam_rms(cn, override):\\n    return _common_cam_rms(cn, lm_override=override)\\n\\n\\ndef main():\\n    ap = argparse.ArgumentParser()\\n    ap.add_argument(\\\"--apply\\\", action=\\\"store_true\\\")\\n    args = ap.parse_args()\\n\\n    observers = pixel_observers(require_existing_cam=False)\\n\\n    new_xyz = {}\\n    keep_clear = []\\n    for lm, policy in TARGETS.items():\\n        meta = md.landmarks_meta.get(lm) or {}\\n        if not meta.get(\\\"z_constraint\\\"):\\n            print(f\\\"SKIP {lm}: pas de z_constraint (deja libere?)\\\")\\n            continue\\n        if policy == \\\"keep\\\":\\n            keep_clear.append(lm)\\n            cur = md.landmarks.get(lm)\\n            print(f\\\"CLEAR  {lm}: constraint retiree, xyz disque conserve (z={cur[2]:+.2f})\\\")\\n            continue\\n        rays = []\\n        for cn in observers.get(lm, []):\\n            if cn not in md.cameras:\\n                continue\\n            cam = get_cam(cn)\\n            try:\\n                d = cam.get_pixel_direction(md.pixels[cn][lm])\\n            except Exception:\\n                continue\\n            if d is not None:\\n                rays.append((md.cameras[cn][\\\"xyz\\\"], d))\\n        if len(rays) < 2:\\n            print(f\\\"SKIP {lm}: <2 rayons, la constraint est porteuse, on n'y touche pas\\\")\\n            continue\\n        p = ray_ls_point(rays)\\n        cur = md.landmarks.get(lm)\\n        new_xyz[lm] = tuple(float(v) for v in p)\\n        dz = \\\"\\\" if cur is None else f\\\" (disque z={cur[2]:+.2f})\\\"\\n        print(f\\\"LIBERE {lm}: LS=({p[0]:.2f}, {p[1]:.2f}, {p[2]:+.2f}){dz}  rays={len(rays)}\\\")\\n\\n    affected = sorted({cn for lm in new_xyz for cn in observers.get(lm, []) if cn in md.pixels})\\n    print(f\\\"\\\\n{'cam affectee':<34}{'avant':>8}{'apres':>8}{'delta':>8}\\\")\\n    worst = 0.0\\n    for cn in affected:\\n        b = cam_rms(cn, {}); a = cam_rms(cn, new_xyz)\\n        if b is not None and a is not None:\\n            worst = max(worst, a - b)\\n            print(f\\\"{cn:<34}{b:>7.2f}'{a:>7.2f}'{a - b:>+7.2f}'\\\")\\n    if worst > 0.25:\\n        print(f\\\"\\\\nATTENTION: regression max {worst:+.2f}' > 0.25' \\u2014 verifier avant d'appliquer\\\")\\n\\n    if not args.apply:\\n        print(\\\"\\\\nDRY-RUN. Relance avec --apply pour ecrire.\\\")\\n        return\\n\\n    shutil.copy(os.path.join(ROOT, \\\"gtamapdata\\\", \\\"landmarks.json\\\"),\\n                os.path.join(ROOT, \\\"gtamapdata\\\", \\\"landmarks.json.bak_waterline\\\"))\\n    for lm, xyz in new_xyz.items():\\n        md.update_landmark(lm, list(xyz), z_constraint=None)\\n    for lm in keep_clear:\\n        cur = md.landmarks.get(lm)\\n        md.update_landmark(lm, list(cur) if cur is not None else None, z_constraint=None)\\n    print(f\\\"\\\\nAPPLIED: {len(new_xyz)} re-triangules + {len(keep_clear)} constraints retirees\\\"\\n          \\\" (backup landmarks.json.bak_waterline)\\\")\\n\\n\\nif __name__ == \\\"__main__\\\":\\n    main()\\n\"}, \"tools/refine/natural_z_sweep.py\": {\"sha_head\": \"2da5cbd14c22\", \"content\": \"#!/usr/bin/env python3\\n\\\"\\\"\\\"natural_z_sweep.py \\u2014 Etend la doctrine waterline aux 19 constraints\\nrestantes a nom naturel et >=2 rayons. Garde par LM: la liberation d'un LM\\nn'est acceptee QUE si aucune cam observatrice ne regresse de plus de --tol\\n(0.25' par defaut) ET que le net s'ameliore ou reste neutre (le but est la\\njustesse du datum, pas le RMS \\u2014 un LM dont la liberation est neutre en RMS\\nmais retire un faux datum est accepte si --allow-neutral).\\n\\nLes LM a 1 source gardent leur constraint (PORTEUSE \\u2014 c'est elle qui fixe le\\npoint). Les noms naturels = NATURAL_WATERLINE_PATTERNS de find_z_candidates.\\n\\nDry-run par defaut; --apply ecrit via md.update_landmark (jamais de bypass).\\nBackup: landmarks.json.bak_zsweep. Roule invariants.py apres.\\n\\\"\\\"\\\"\\nimport argparse, json, math, os, re, shutil, sys\\n\\nimport numpy as np\\n\\nROOT = os.path.dirname(os.path.dirname(os.path.dirname(os.path.abspath(__file__))))\\nsys.path.insert(0, ROOT)\\nimport gtamapdata as md\\nsys.path.insert(0, os.path.join(ROOT, \\\"tools\\\"))\\nfrom common import cam_rms as _common_cam_rms, get_cam, pixel_observers, ray_ls_point\\n\\nNATURAL = re.compile(\\n    r'\\\\b(Island|Key|Bay|Beach|Coast|Shore|Shoreline|Lagoon|Inlet|Cove|'\\n    r'Mangrove|Surf|Ocean|Reef|Sandbar|Boat|Buoy)\\\\b', re.I)\\n\\n\\ndef cam_rms(cn, override):\\n    return _common_cam_rms(cn, lm_override=override)\\n\\n\\ndef main():\\n    ap = argparse.ArgumentParser()\\n    ap.add_argument(\\\"--tol\\\", type=float, default=0.25)\\n    ap.add_argument(\\\"--allow-neutral\\\", action=\\\"store_true\\\", default=True)\\n    ap.add_argument(\\\"--apply\\\", action=\\\"store_true\\\")\\n    args = ap.parse_args()\\n\\n    observers = pixel_observers()\\n\\n    accepted, rejected, kept = {}, [], []\\n    for lm_name in sorted(md.landmarks_meta):\\n        meta = md.landmarks_meta[lm_name] or {}\\n        zc = meta.get(\\\"z_constraint\\\")\\n        if not zc or zc.get(\\\"type\\\") != \\\"fixed\\\" or not NATURAL.search(lm_name):\\n            continue\\n        rays = []\\n        for cn in observers.get(lm_name, []):\\n            cam = get_cam(cn)\\n            try:\\n                d = cam.get_pixel_direction(md.pixels[cn][lm_name])\\n            except Exception:\\n                continue\\n            if d is not None:\\n                rays.append((md.cameras[cn][\\\"xyz\\\"], d))\\n        if len(rays) < 2:\\n            kept.append(lm_name)\\n            continue\\n        p = tuple(float(v) for v in ray_ls_point(rays))\\n        aff = observers.get(lm_name, [])\\n        deltas = {}\\n        ok = True\\n        worst = net = 0.0\\n        for cn in aff:\\n            b = cam_rms(cn, {}); a = cam_rms(cn, {lm_name: p})\\n            if b is None or a is None:\\n                continue\\n            deltas[cn] = a - b\\n            worst = max(worst, a - b); net += a - b\\n        if worst > args.tol or (net > 1e-6 and not args.allow_neutral) or net > args.tol:\\n            ok = False\\n        cur_z = md.landmarks[lm_name][2] if md.landmarks.get(lm_name) is not None else None\\n        line = (f\\\"{lm_name}: z {cur_z:+.2f} -> {p[2]:+.2f} (rays={len(rays)}) \\\"\\n                f\\\"worst={worst:+.2f}' net={net:+.2f}'\\\")\\n        if ok:\\n            accepted[lm_name] = p\\n            print(\\\"LIBERE\\\", line)\\n        else:\\n            rejected.append(lm_name)\\n            print(\\\"REJETE\\\", line, \\\"(garde: constraint conservee)\\\")\\n\\n    print(f\\\"\\\\n# {len(accepted)} liberes, {len(rejected)} rejetes par le garde, \\\"\\n          f\\\"{len(kept)} a 1 source (constraints porteuses, conservees)\\\")\\n\\n    if not args.apply:\\n        print(\\\"DRY-RUN. Relance avec --apply pour ecrire.\\\")\\n        return\\n    if not accepted:\\n        print(\\\"Rien a ecrire.\\\")\\n        return\\n    shutil.copy(os.path.join(ROOT, \\\"gtamapdata\\\", \\\"landmarks.json\\\"),\\n                os.path.join(ROOT, \\\"gtamapdata\\\", \\\"landmarks.json.bak_zsweep\\\"))\\n    for lm, xyz in accepted.items():\\n        md.update_landmark(lm, list(xyz), z_constraint=None)\\n    print(f\\\"APPLIED: {len(accepted)} LM liberes (backup landmarks.json.bak_zsweep)\\\")\\n\\n\\nif __name__ == \\\"__main__\\\":\\n    main()\\n\"}, \"tools/refine/clean_provenance.py\": {\"sha_head\": \"4844dddde27a\", \"content\": \"#!/usr/bin/env python3\\n\\\"\\\"\\\"clean_provenance.py \\u2014 Nettoie la dette de provenance identifiee le\\n2026-06-10 (32 refs orphelines + 1 entree pixels morte).\\n\\nCONTEXTE (verifie avant d'ecrire cet outil):\\n- 'Port Gellhorn Postcard' (cam supprimee) a laisse 78 markings dans\\n  pixels.json. Ce n'est PAS un rename de 'Port Gellhorn Postcard (X)': les\\n  67 LMs communs ont des pixels completement differents (crops/frames\\n  distincts). Sans entree camera (pose+intrinsics supprimees), ces markings\\n  sont des rayons sans origine: inutilisables. PURGE (l'archive = git).\\n- Les source_cameras orphelines (26x 'Port Gellhorn Postcard', 3x 'Gizmo',\\n  3x 'Penthouse (SE/NE/SW)') deviennent des marqueurs \\\"(legacy: NAME)\\\" \\u2014\\n  l'historique est preserve sans pretendre une source vivante (precedent:\\n  \\\"(geometric: ...)\\\"). Aucun changement de comportement FIXED: une source\\n  inconnue et un marqueur retournent tous deux non-trusted.\\n- CONSEQUENCE ASSUMEE: les ~41 'Bay (...)' de port_gellhorn restent a 1 rayon\\n  -> leurs z_constraints sont PORTEUSES et conservees. Le T3 apportera les\\n  seconds rayons; a ce moment natural_z_sweep.py pourra les liberer.\\n\\nEcrit via md.update_landmark (source_cameras param) pour les LMs; pixels.json\\nest edite par chargement/sauvegarde du JSON complet, SEULE operation sans API\\n(suppression de cle \\u2014 update_* ne couvre pas pixels), backup .bak_provenance.\\nDry-run par defaut; --apply pour ecrire. Roule invariants.py apres: les WARN\\ndoivent tomber a 0.\\n\\\"\\\"\\\"\\nimport argparse, json, os, shutil, sys\\n\\nROOT = os.path.dirname(os.path.dirname(os.path.dirname(os.path.abspath(__file__))))\\nsys.path.insert(0, ROOT)\\nimport gtamapdata as md\\nsys.path.insert(0, os.path.join(ROOT, \\\"tools\\\"))\\nfrom common import save_json\\n\\nDEAD_PIXEL_CAMS = [\\\"Port Gellhorn Postcard\\\"]\\nORPHANS = {\\\"Port Gellhorn Postcard\\\", \\\"Gizmo\\\", \\\"Penthouse (SE)\\\", \\\"Penthouse (NE)\\\", \\\"Penthouse (SW)\\\"}\\n\\n\\ndef main():\\n    ap = argparse.ArgumentParser()\\n    ap.add_argument(\\\"--apply\\\", action=\\\"store_true\\\")\\n    args = ap.parse_args()\\n\\n    # 1. LMs avec sources orphelines -> marqueurs legacy\\n    to_fix = []\\n    for n, m in md.landmarks_meta.items():\\n        srcs = (m or {}).get(\\\"source_cameras\\\") or []\\n        if any(s in ORPHANS for s in srcs):\\n            new_srcs = [f\\\"(legacy: {s})\\\" if s in ORPHANS else s for s in srcs]\\n            to_fix.append((n, srcs, new_srcs))\\n    for n, old, new in to_fix:\\n        print(f\\\"PROVENANCE {n}: {old} -> {new}\\\")\\n\\n    # 2. entrees pixels mortes\\n    px_path = os.path.join(ROOT, \\\"gtamapdata\\\", \\\"pixels.json\\\")\\n    with open(px_path) as f:\\n        px = json.load(f)\\n    dead = [c for c in DEAD_PIXEL_CAMS if c in px]\\n    for c in dead:\\n        print(f\\\"PURGE pixels: '{c}' ({len(px[c])} markings sans camera \\u2014 archive = git history)\\\")\\n\\n    print(f\\\"\\\\n# {len(to_fix)} LMs a corriger, {len(dead)} entree(s) pixels a purger\\\")\\n    if not args.apply:\\n        print(\\\"DRY-RUN. Relance avec --apply pour ecrire.\\\")\\n        return\\n\\n    shutil.copy(os.path.join(ROOT, \\\"gtamapdata\\\", \\\"landmarks.json\\\"),\\n                os.path.join(ROOT, \\\"gtamapdata\\\", \\\"landmarks.json.bak_provenance\\\"))\\n    shutil.copy(px_path, px_path + \\\".bak_provenance\\\")\\n    for n, _old, new in to_fix:\\n        cur = md.landmarks.get(n)\\n        md.update_landmark(n, list(cur) if cur is not None else None, source_cameras=new)\\n    for c in dead:\\n        del px[c]\\n    save_json(px_path, px)  # convention projet: indent=2, ordre preserve\\n    print(f\\\"APPLIED: {len(to_fix)} LMs + {len(dead)} purge(s) (backups .bak_provenance)\\\")\\n\\n\\nif __name__ == \\\"__main__\\\":\\n    main()\\n\"}, \"tools/refine/guarded_apply.py\": {\"sha_head\": \"7c49924c2525\", \"content\": \"#!/usr/bin/env python3\\n\\\"\\\"\\\"guarded_apply.py \\u2014 Disk-verified selective apply of bundle_adjust_result.json.\\n\\nProblem this solves (proven 2026-06-10 full-rerun experiment): a global BA can\\nreport -80% on its own weighted loss while WORSENING 29/95 cams at equal weight,\\nbecause shared LMs get dragged to a compromise that sacrifices leak-cam rays\\n(e.g. Pool 0'->416', Police Chase (D) leak 1.6'->133' without the cams moving).\\n\\nStrategy: hill-climbing over individual deltas.\\n  Candidates = each LM move, each cam move, and each (cam + its updated child\\n  LMs) bundle. A candidate is ACCEPTED only if, re-evaluated on the CURRENT\\n  accepted state with the exact tier formula (dx*hfov/w*60):\\n    - no affected cam regresses more than --tol arcmin (default 0.25), AND\\n    - net sum of affected-cam RMS strictly improves.\\n  Multi-pass until a full pass accepts nothing.\\n\\nDoctrine blacklist (cam moves never applied): Amphitheater (contradictory hard\\nanchors, stays on rlx pose), Beach (ground-projection cam, z/pitch critical,\\npixel RMS does not capture coastline quality), Vice City Sign (2-LM\\nunder-determined, BA teleports it 68m with full freedom).\\n\\nDry-run by default; --apply writes via md.update_camera/update_landmark and\\nbacks up .bak_guarded first.\\n\\\"\\\"\\\"\\nimport argparse, copy, json, math, os, shutil, sys\\n\\nROOT = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))\\nsys.path.insert(0, os.path.dirname(ROOT)) if os.path.basename(ROOT) == \\\"tools\\\" else None\\nPROJ = os.path.dirname(ROOT) if os.path.basename(ROOT) == \\\"tools\\\" else ROOT\\nsys.path.insert(0, PROJ)\\n\\nimport gtamapdata as md\\nsys.path.insert(0, os.path.join(PROJ, \\\"tools\\\"))\\nfrom common import cam_rms as _common_cam_rms\\n\\nCAM_BLACKLIST_DEFAULT = [\\\"Amphitheater\\\", \\\"Beach\\\", \\\"Vice City Sign\\\"]\\n\\n\\ndef snap_z(lm_name, xyz):\\n    \\\"\\\"\\\"Apply the SAME z_constraint snap that md.update_landmark applies at write\\n    time, so the guard validates exactly the geometry that will hit the disk\\n    (lesson: 2026-06-10, Island G/K \\u2014 free-z validated, snapped-z written).\\\"\\\"\\\"\\n    meta = md.landmarks_meta.get(lm_name) or {}\\n    zc = meta.get(\\\"z_constraint\\\")\\n    if zc and zc.get(\\\"type\\\") == \\\"fixed\\\":\\n        xyz = list(xyz)\\n        xyz[2] = float(zc[\\\"value\\\"])\\n    return list(xyz)\\n\\n\\ndef build_state():\\n    cams = {n: {\\\"xyz\\\": list(c[\\\"xyz\\\"]), \\\"ypr\\\": list(c[\\\"ypr\\\"]), \\\"fov\\\": list(c[\\\"fov\\\"])}\\n            for n, c in md.cameras.items()}\\n    lms = {n: (list(xyz) if xyz is not None else None) for n, xyz in md.landmarks.items()}\\n    return cams, lms\\n\\n\\ndef cam_rms(cam_name, cams, lms):\\n    return _common_cam_rms(cam_name, cam_state=cams.get(cam_name), lms=lms)\\n\\n\\ndef main():\\n    ap = argparse.ArgumentParser()\\n    ap.add_argument(\\\"--result\\\", default=os.path.join(PROJ, \\\"tools\\\", \\\"bundle_adjust_result.json\\\"))\\n    ap.add_argument(\\\"--tol\\\", type=float, default=0.25, help=\\\"max per-cam regression accepted (arcmin)\\\")\\n    ap.add_argument(\\\"--blacklist-cam\\\", nargs=\\\"*\\\", default=CAM_BLACKLIST_DEFAULT)\\n    ap.add_argument(\\\"--apply\\\", action=\\\"store_true\\\")\\n    args = ap.parse_args()\\n\\n    with open(args.result) as f:\\n        result = json.load(f)\\n    cam_updates = result.get(\\\"cameras\\\", {})\\n    lm_updates = result.get(\\\"landmarks\\\", {})\\n\\n    # observers index: lm -> cams that mark it\\n    observers = {}\\n    for c, obs in md.pixels.items():\\n        for l in obs:\\n            observers.setdefault(l, set()).add(c)\\n\\n    cams, lms = build_state()\\n\\n    # baseline RMS for EVERY cam: regression budget is cumulative vs this,\\n    # so many small accepted deltas can never silently stack on one victim.\\n    baseline0 = {c: cam_rms(c, cams, lms) for c in md.pixels if c in cams}\\n\\n    def affected_for(delta):\\n        aff = set()\\n        for cn in delta.get(\\\"cams\\\", {}):\\n            aff.add(cn)\\n            # moving a cam changes nothing for others directly (LMs handled separately)\\n        for ln in delta.get(\\\"lms\\\", {}):\\n            aff |= observers.get(ln, set())\\n        return {a for a in aff if a in md.pixels}\\n\\n    def try_delta(delta):\\n        aff = affected_for(delta)\\n        if not aff:\\n            return False, 0.0\\n        before = {a: cam_rms(a, cams, lms) for a in aff}\\n        # stage\\n        staged_c = {cn: copy.deepcopy(cams[cn]) for cn in delta.get(\\\"cams\\\", {}) if cn in cams}\\n        staged_l = {ln: list(lms[ln]) for ln in delta.get(\\\"lms\\\", {}) if ln in lms}\\n        for cn, upd in delta.get(\\\"cams\\\", {}).items():\\n            if cn in cams:\\n                if upd.get(\\\"xyz\\\") is not None: cams[cn][\\\"xyz\\\"] = list(upd[\\\"xyz\\\"])\\n                if upd.get(\\\"ypr\\\") is not None: cams[cn][\\\"ypr\\\"] = list(upd[\\\"ypr\\\"])\\n                if upd.get(\\\"hfov\\\") is not None: cams[cn][\\\"fov\\\"] = [upd[\\\"hfov\\\"], None]\\n                elif upd.get(\\\"fov\\\") is not None: cams[cn][\\\"fov\\\"] = list(upd[\\\"fov\\\"])\\n        for ln, xyz in delta.get(\\\"lms\\\", {}).items():\\n            if ln in lms and lms[ln] is not None:\\n                lms[ln] = list(xyz)\\n        after = {a: cam_rms(a, cams, lms) for a in aff}\\n        valid = [a for a in aff if before[a] is not None and after[a] is not None]\\n        # cumulative guard: regression measured against the session baseline\\n        worst = max((after[a] - (baseline0.get(a) if baseline0.get(a) is not None else before[a])) for a in valid)\\n        net = sum((after[a] - before[a]) for a in valid)\\n        if worst <= args.tol and net < -1e-6:\\n            return True, net\\n        # rollback\\n        for cn, st in staged_c.items():\\n            cams[cn] = st\\n        for ln, xyz in staged_l.items():\\n            lms[ln] = xyz\\n        return False, net\\n\\n    # build candidates\\n    candidates = []\\n    for ln, xyz in lm_updates.items():\\n        candidates.append({\\\"name\\\": f\\\"LM {ln}\\\", \\\"lms\\\": {ln: snap_z(ln, xyz)}})\\n    for cn, upd in cam_updates.items():\\n        if cn in args.blacklist_cam:\\n            continue\\n        candidates.append({\\\"name\\\": f\\\"CAM {cn}\\\", \\\"cams\\\": {cn: upd}})\\n        child = {l: snap_z(l, lm_updates[l]) for l in md.pixels.get(cn, {}) if l in lm_updates}\\n        if child:\\n            candidates.append({\\\"name\\\": f\\\"BUNDLE {cn} (+{len(child)} LMs)\\\", \\\"cams\\\": {cn: upd}, \\\"lms\\\": child})\\n\\n    accepted, n_pass = [], 0\\n    while True:\\n        n_pass += 1\\n        got = 0\\n        for cand in candidates:\\n            if cand.get(\\\"_done\\\"):\\n                continue\\n            ok, net = try_delta(cand)\\n            if ok:\\n                cand[\\\"_done\\\"] = True\\n                accepted.append((cand[\\\"name\\\"], net))\\n                got += 1\\n        print(f\\\"# pass {n_pass}: accepted {got}\\\")\\n        if got == 0:\\n            break\\n\\n    rejected = [c[\\\"name\\\"] for c in candidates if not c.get(\\\"_done\\\")]\\n    print(f\\\"\\\\n# ACCEPTED {len(accepted)} deltas | REJECTED {len(rejected)} | tol={args.tol}' | blacklist={args.blacklist_cam}\\\")\\n    for name, net in sorted(accepted, key=lambda x: x[1])[:15]:\\n        print(f\\\"  {net:+9.2f}'  {name}\\\")\\n    if len(accepted) > 15:\\n        print(f\\\"  ... +{len(accepted)-15} more\\\")\\n\\n    if not args.apply:\\n        print(\\\"\\\\nDRY-RUN. Re-run with --apply to write.\\\")\\n        return\\n\\n    for p in (\\\"cameras.json\\\", \\\"landmarks.json\\\"):\\n        shutil.copy(os.path.join(PROJ, \\\"gtamapdata\\\", p), os.path.join(PROJ, \\\"gtamapdata\\\", p + \\\".bak_guarded\\\"))\\n    n_c = n_l = 0\\n    base_cams, _ = build_state()\\n    for cn, st in cams.items():\\n        if st != base_cams.get(cn):\\n            md.update_camera(cn, xyz=st[\\\"xyz\\\"], ypr=st[\\\"ypr\\\"], fov=st[\\\"fov\\\"])\\n            n_c += 1\\n    for ln, xyz in lms.items():\\n        if xyz is None:\\n            continue\\n        cur = md.landmarks.get(ln)\\n        if cur is None or list(cur) != list(xyz):\\n            md.update_landmark(ln, xyz)\\n            n_l += 1\\n    print(f\\\"\\\\nAPPLIED: {n_c} cams, {n_l} landmarks written (backups .bak_guarded).\\\")\\n\\n\\nif __name__ == \\\"__main__\\\":\\n    main()\\n\"}}")

todo = []
for rel, item in PAYLOAD.items():
    path = os.path.join(PROJ, rel)
    if not os.path.exists(path):
        todo.append(("create", rel, item["content"]))
        continue
    cur = open(path).read()
    if cur == item["content"]:
        print(f"SKIP {rel}: deja a jour")
        continue
    if "from common import" in cur:
        print(f"SKIP {rel}: deja refactore (version differente — verifier manuellement)")
        continue
    if item["sha_head"] and hashlib.sha256(cur.encode()).hexdigest()[:12] != item["sha_head"]:
        sys.exit(f"ERROR {rel}: a derive du HEAD 213e4b9 attendu — abort")
    todo.append(("patch", rel, item["content"]))

if not todo:
    sys.exit(0)
for action, rel, _ in todo:
    print(("APPLY " if APPLY else "WOULD APPLY ") + action + " " + rel)
if not APPLY:
    print("DRY-RUN: rien ecrit. Relance avec --apply.")
    sys.exit(0)
for action, rel, content in todo:
    path = os.path.join(PROJ, rel)
    if action == "patch":
        shutil.copy(path, path + ".bak_common")
    open(path, "w").write(content)
